SELECT a.id, a.apt_no, a.warehouse_id, a.slot_template_id, a.apt_date, a.apt_slot, a.task_type, a.plate_no, a.driver_name, a.driver_phone, a.container_no, a.source_order_no, a.status, a.yard_task_id, a.cancel_reason, a.remark, a.create_time FROM yms_appointment a WHERE a.deleted = 0
AND a.warehouse_id = #{bo.warehouseId}
AND a.apt_date = #{bo.aptDate}
AND a.status = #{bo.status}
AND a.plate_no LIKE CONCAT('%', #{bo.plateNo}, '%')
AND a.driver_name LIKE CONCAT('%', #{bo.driverName}, '%')
AND a.container_no LIKE CONCAT('%', #{bo.containerNo}, '%')
AND a.task_type = #{bo.taskType}
ORDER BY a.apt_date DESC, a.apt_slot ASC, a.create_time DESC

SELECT COUNT(1) FROM yms_appointment
WHERE deleted = 0
  AND warehouse_id = #{warehouseId}
  AND apt_date = #{aptDate}
  AND apt_slot = #{aptSlot}
  AND status NOT IN ('CANCELLED', 'NO_SHOW')
